import { CDK_ACCORDION, CdkAccordion } from '@angular/cdk/accordion';
import { BooleanInput, coerceBooleanProperty } from '@angular/cdk/coercion';
import {
  AfterContentInit,
  booleanAttribute,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ContentChildren,
  DoCheck,
  EventEmitter,
  forwardRef,
  HostBinding,
  inject,
  Injector,
  Input,
  OnChanges,
  OnDestroy,
  OnInit,
  Output,
  QueryList,
  SimpleChanges,
  ViewEncapsulation,
} from '@angular/core';
import { FormGroupDirective, NG_VALUE_ACCESSOR, NgControl, NgForm, NgModel } from '@angular/forms';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import {
  ErrorState,
  randomString,
  voidFn,
} from '@questrade/allspark-angular-components/core/utils';
import {
  ErrorStateMatcher,
  ErrorStateMatcherInterface,
  FormFieldControl,
} from '@questrade/allspark-angular-components/form-control';
import { Subject, takeUntil } from 'rxjs';
import { QRadioButtonComponent } from '../radio-button/radio-button.component';
import { QRadioButtonChangeEvent } from '../types/radio-button-change-event.interface';
import { QRadioButtonVariant } from '../types/radio-button-variant.type';
import { QRadioLabelGap } from '../types/radio-label-gap.type';

const RADIO_GROUP_VALUE_ACCESSOR = {
  provide: NG_VALUE_ACCESSOR,
  useExisting: forwardRef(() => QRadioGroupComponent),
  multi: true,
};

@Component({
  providers: [
    QDestroyService,
    RADIO_GROUP_VALUE_ACCESSOR,
    { provide: FormFieldControl, useExisting: QRadioGroupComponent },
    { provide: CDK_ACCORDION, useExisting: forwardRef(() => QRadioGroupComponent) },
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  selector: 'q-radio-group',
  template: `<ng-content />`,
  styles: [
    `
      @use '../../styles/typography';

      .q-radio-group {
        @include typography.q-body-m;

        display: flex;
        flex-direction: var(--awds-radio-group-flex-direction, column);
        gap: var(--awds-radio-group-gap, var(--ads-size-xxxs) 0);
      }
    `,
  ],
})
export class QRadioGroupComponent
  extends ErrorState
  implements OnInit, AfterContentInit, DoCheck, OnDestroy, CdkAccordion, OnChanges
{
  @Output() readonly radioGroupChange = new EventEmitter<QRadioButtonChangeEvent>();

  @Input() override errorStateMatcher: ErrorStateMatcherInterface = new ErrorStateMatcher();
  @Input() labelGap: QRadioLabelGap | null = 's';
  @Input() variant: QRadioButtonVariant | null = 'default';
  @Input({ transform: booleanAttribute }) @HostBinding('class.q-radio-group-invalid') invalidState =
    false;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-radio-group';

  @Input() get value(): unknown {
    return this._value;
  }
  set value(newValue: unknown) {
    if (this._value !== newValue) {
      this._value = newValue;
      this._updateSelectedRadioFromValue();
      this._checkSelectedRadioButton();
    }
  }

  @Input() get name(): string {
    return this._name;
  }
  set name(value: string) {
    this._name = value;
    this._updateRadioButtonNames();
  }

  @Input() get selected(): QRadioButtonComponent | null {
    return this._selected;
  }
  set selected(selected: QRadioButtonComponent | null) {
    this._selected = selected;
    this.value = selected ? selected.value : null;
    this._checkSelectedRadioButton();
  }

  @Input() get disabled(): boolean {
    return this._disabled;
  }
  set disabled(value: BooleanInput) {
    this._disabled = coerceBooleanProperty(value);
    this._markRadiosForCheck();
  }

  @Input() get required(): boolean {
    return this._required;
  }
  set required(value: BooleanInput) {
    this._required = coerceBooleanProperty(value);
    this._markRadiosForCheck();
  }

  @ContentChildren(forwardRef(() => QRadioButtonComponent), { descendants: true })
  _radios!: QueryList<QRadioButtonComponent>;

  @HostBinding('class') hostClass = 'q-radio-group';
  @HostBinding('attr.role') hostRole = 'radiogroup';

  _controlValueAccessorChangeFn: (value: unknown) => void = voidFn;
  _onTouched: () => unknown = voidFn;

  // #region: CdkAccordion implementation
  readonly _stateChanges = new Subject<SimpleChanges>();
  readonly _openCloseAllActions = new Subject<boolean>();
  readonly id = `q-radio-group-${randomString()}`;
  multi = false;
  // #endregion

  private _value: unknown | null = null;
  private _name = `q-radio-group-${randomString()}`;
  private _selected: QRadioButtonComponent | null = null;
  private _isInitialized = false;
  private _disabled = false;
  private _required = false;
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _destroy$ = inject(QDestroyService);
  private readonly injector = inject(Injector);

  constructor() {
    super(inject(FormGroupDirective, { optional: true }), inject(NgForm, { optional: true }));
  }

  ngOnInit(): void {
    this._setComponentControl();
  }

  ngOnChanges(changes: SimpleChanges): void {
    this._stateChanges.next(changes);
  }

  ngOnDestroy(): void {
    this._stateChanges.complete();
    this._openCloseAllActions.complete();
  }

  ngDoCheck(): void {
    if (this.ngControl) {
      this._updateErrorState();

      if (!(this.ngControl instanceof NgModel)) {
        this.invalidState = this.errorState;
      }
    }
  }

  ngAfterContentInit(): void {
    this._isInitialized = true;
    this._setRadiosSub();
  }

  // CdkAccordion implementation
  openAll(): void {
    if (this.multi) {
      this._openCloseAllActions.next(true);
    }
  }

  // CdkAccordion implementation
  closeAll(): void {
    this._openCloseAllActions.next(false);
  }

  _checkSelectedRadioButton(): void {
    if (this._selected && !this._selected.checked) {
      this._selected.checked = true;
    }
  }

  _touch(): void {
    if (this._onTouched) {
      this._onTouched();
    }
  }

  _emitChangeEvent(): void {
    if (this._isInitialized) {
      this.radioGroupChange.emit({
        value: this._value,
        ...(this._selected && { source: this._selected }),
        ...(this._selected && { target: this._selected._elementRef }),
      });
    }
  }

  _markRadiosForCheck(): void {
    if (this._radios) {
      this._radios.forEach((radio) => radio._markForCheck());
    }
  }

  _setRadiosSub(): void {
    this._radios.changes.pipe(takeUntil(this._destroy$)).subscribe(() => {
      if (this.selected && !this._radios.find((radio) => radio === this.selected)) {
        this._selected = null;
      }
    });
  }

  writeValue(value: unknown): void {
    this.value = value;
    this._cdr.markForCheck();
  }

  registerOnChange(fn: (value: unknown) => void): void {
    this._controlValueAccessorChangeFn = fn;
  }

  registerOnTouched(fn: () => unknown): void {
    this._onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.disabled = isDisabled;
    this._cdr.markForCheck();
  }

  private _setComponentControl(): void {
    const injectedControl = this.injector.get(NgControl, null);

    if (injectedControl) {
      this.ngControl = injectedControl;
    }
  }

  private _updateRadioButtonNames(): void {
    if (this._radios) {
      this._radios.forEach((radio) => {
        radio.name = this.name;
        radio._markForCheck();
      });
    }
  }

  private _updateSelectedRadioFromValue(): void {
    const isAlreadySelected = this._selected !== null && this._selected.value === this._value;

    if (this._radios && !isAlreadySelected) {
      this._selected = null;
      this._radios.forEach((radio: QRadioButtonComponent) => {
        radio.checked = this.value === radio.value;
        if (radio.checked) {
          this._selected = radio;
        }
      });
    }
  }
}
