import { FocusMonitor } from '@angular/cdk/a11y';
import {
  BooleanInput,
  NumberInput,
  coerceBooleanProperty,
  coerceCssPixelValue,
  coerceNumberProperty,
} from '@angular/cdk/coercion';
import { UniqueSelectionDispatcher } from '@angular/cdk/collections';
import { NgClass, NgIf, NgStyle, NgSwitch, NgSwitchCase, NgTemplateOutlet } from '@angular/common';
import {
  AfterViewInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  DoCheck,
  ElementRef,
  EventEmitter,
  HostBinding,
  HostListener,
  Input,
  OnDestroy,
  OnInit,
  Output,
  TemplateRef,
  ViewChild,
  ViewEncapsulation,
  booleanAttribute,
  inject,
} from '@angular/core';
import { QExpansionTriggerComponent } from '@questrade/allspark-angular-components/core/components';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import { randomString, voidFn } from '@questrade/allspark-angular-components/core/utils';
import { takeUntil } from 'rxjs';
import { QRadioContainerComponent } from '../radio-container/radio-container.component';
import { QRadioExpandableComponent } from '../radio-expandable/radio-expandable.component';
import { QRadioGroupComponent } from '../radio-group/radio-group.component';
import { QRadioButtonChangeEvent } from '../types/radio-button-change-event.interface';
import { QRadioButtonVariant } from '../types/radio-button-variant.type';
import { QRadioContainerDensity } from '../types/radio-container-density.type';
import { QRadioExtraContentDensity } from '../types/radio-extra-content-density.type';
import { QRadioExtraContentPosition } from '../types/radio-extra-content-position.type';
import { QRadioLabelGap } from '../types/radio-label-gap.type';

@Component({
  imports: [
    NgIf,
    NgClass,
    NgStyle,
    NgSwitch,
    NgSwitchCase,
    NgTemplateOutlet,
    QRadioContainerComponent,
    QRadioExpandableComponent,
    QExpansionTriggerComponent,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  selector: 'q-radio-button',
  templateUrl: './radio-button.component.html',
  styleUrls: ['./radio-button.component.scss'],
  providers: [QDestroyService],
})
export class QRadioButtonComponent implements OnInit, AfterViewInit, OnDestroy, DoCheck {
  @Output() readonly radioButtonChange = new EventEmitter<QRadioButtonChangeEvent>();
  @Output() readonly expandedChange = new EventEmitter<boolean>();

  @Input('aria-label') ariaLabel!: string;
  @Input('aria-labelledby') ariaLabelledby!: string;
  @Input('aria-describedby') ariaDescribedby!: string;
  @Input() containerDensity: QRadioContainerDensity = 'default';
  @Input() extraContent: TemplateRef<unknown> | null = null;
  @Input() extraContentContext: unknown | null = null;
  @Input() extraContentDensity: QRadioExtraContentDensity = 'xs';
  @Input() extraContentPosition: QRadioExtraContentPosition = 'below';
  @Input() id = `q-radio-button-${randomString()}`;
  @Input() labelGap: QRadioLabelGap = 's';
  @Input() name!: string;
  @Input() variant: QRadioButtonVariant = 'default';
  @Input({ transform: booleanAttribute }) readonly = false;
  @Input({ transform: booleanAttribute }) expanded = false;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-radio-button';

  @Input() get checked(): boolean {
    return this._checked;
  }
  set checked(value: BooleanInput) {
    this._updateCheckedState(coerceBooleanProperty(value));
  }

  @Input() get value(): unknown {
    return this._value;
  }
  set value(value: unknown) {
    this._updateValue(value);
  }

  @Input() get disabled(): boolean {
    return this._disabled || (this._radioGroup !== null && this._radioGroup.disabled);
  }
  set disabled(value: BooleanInput) {
    this._setDisabled(coerceBooleanProperty(value));
  }

  @Input() get required(): boolean {
    return this._required || !!(this._radioGroup && this._radioGroup.required);
  }
  set required(value: BooleanInput) {
    this._required = coerceBooleanProperty(value);
  }

  @Input() get tabIndex(): number {
    return this.disabled ? -1 : this._tabIndex;
  }
  set tabIndex(value: NumberInput) {
    this._tabIndex = coerceNumberProperty(value, 0);
  }

  @Input() get extraContentRightWidth(): string {
    return this._rightExtraContentWidth;
  }
  set extraContentRightWidth(value: NumberInput) {
    this._rightExtraContentWidth = coerceCssPixelValue(value);
  }

  @Input() get invalidState(): boolean {
    return this._invalidState;
  }
  set invalidState(value: BooleanInput) {
    this._invalidState = coerceBooleanProperty(value);
  }

  @ViewChild('inputRef') _inputElement!: ElementRef<HTMLInputElement>;
  @ViewChild(QRadioExpandableComponent) _radioExpandable!: QRadioExpandableComponent;
  @ViewChild(QExpansionTriggerComponent) _expansionTrigger!: QExpansionTriggerComponent;

  @HostBinding('attr.tabindex') hostTabIndex: string | null = null;
  @HostBinding('attr.aria-label') hostAriaLabel: string | null = null;
  @HostBinding('attr.aria-labelledby') hostAriaLabelledBy: string | null = null;
  @HostBinding('attr.aria-describedby') hostAriaDescribedBy: string | null = null;
  @HostBinding('attr.id') get hostId(): string {
    return this.id;
  }
  @HostBinding('class') get hostClassNames(): string {
    return [
      'q-radio-button',
      `q-radio-button-variant-${this.currentVariant}`,
      `q-radio-button-container-density-${this.containerDensity}`,
      this.checked && 'q-radio-button-checked',
      this.disabled && 'q-radio-button-disabled',
      this.readonly && 'q-radio-button-readonly',
      this.currentInvalidState && 'q-radio-button-invalid',
    ]
      .filter(Boolean)
      .join(' ');
  }

  @HostListener('focus') onFocus(): void {
    this._inputElement.nativeElement.focus();
  }

  _radioGroup: QRadioGroupComponent | null = inject(QRadioGroupComponent, { optional: true });
  readonly _elementRef = inject(ElementRef);

  private _checked = false;
  private _value: unknown | null = null;
  private _disabled = false;
  private _required = false;
  private _invalidState = false;
  private _tabIndex = 0;
  private _rightExtraContentWidth = '';
  private _previousTabIndex: number | undefined;
  private _removeUniqueSelectionListener: () => void = () => voidFn;
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _radioDispatcher = inject(UniqueSelectionDispatcher);
  private readonly _focusMonitor = inject(FocusMonitor);
  private readonly _destroy$ = inject(QDestroyService);

  ngOnInit(): void {
    this._setInitialState();
    this._setRadioDispatcher();
  }

  ngAfterViewInit(): void {
    this._updateTabIndex();
    this._setFocusMonitor();
  }

  ngDoCheck(): void {
    this._updateTabIndex();
  }

  ngOnDestroy(): void {
    this._focusMonitor.stopMonitoring(this._elementRef);
    this._removeUniqueSelectionListener();
  }

  _onLabelInteraction(): void {
    if (this.currentVariant === 'expandable' && !this.disabled && !this.readonly) {
      this._expansionTrigger.onTriggerInteraction();
    }
  }

  _onExpandedChange(expanded: boolean): void {
    this.expanded = expanded;
    this.expandedChange.emit(expanded);
  }

  _onRadioContainerChange(event: Event): void {
    if (this.currentVariant === 'container') {
      this._onInputInteraction(event);
    }
  }

  _markForCheck(): void {
    this._cdr.markForCheck();
  }

  _onInputInteraction(event: Event | null): void {
    event?.stopPropagation();

    if (!this.checked && !this.disabled && !this.readonly) {
      const groupValueChanged = this._radioGroup && this.value !== this._radioGroup.value;
      this.checked = true;
      this._radioGroup?._markRadiosForCheck();

      this._emitChangeEvent();

      if (this._radioGroup) {
        this._radioGroup?._controlValueAccessorChangeFn(this.value);
        if (groupValueChanged) {
          this._radioGroup._emitChangeEvent();
        }
      }
    }
  }

  _onTouchTargetClick(event: Event): void {
    if (this.currentVariant === 'expandable') {
      return;
    }

    this._onInputInteraction(event);

    if (!this.disabled) {
      this._inputElement.nativeElement.focus();
    }
  }

  _onInputClick(event: Event): void {
    if (this.readonly) {
      event.preventDefault();
      event.stopPropagation();
    }
  }

  get currentVariant(): QRadioButtonVariant {
    return this._radioGroup?.variant || this.variant;
  }

  get currentInvalidState(): boolean {
    return this._radioGroup?.invalidState || this.invalidState;
  }

  get currentLabelGap(): QRadioLabelGap {
    return this._radioGroup?.labelGap || this.labelGap;
  }

  get canRenderExtraContentBelow(): boolean {
    return (
      this.currentVariant === 'default' &&
      this.extraContentPosition === 'below' &&
      !!this.extraContent
    );
  }

  get canRenderExtraContentRight(): boolean {
    return (
      this.currentVariant === 'container' &&
      this.extraContentPosition === 'right' &&
      !!this.extraContent
    );
  }

  private _updateCheckedState(newCheckedState: boolean): void {
    if (this._checked !== newCheckedState) {
      this._checked = newCheckedState;
      if (newCheckedState && this._radioGroup && this._radioGroup.value !== this.value) {
        this._radioGroup.selected = this;
      } else if (!newCheckedState && this._radioGroup && this._radioGroup.value === this.value) {
        this._radioGroup.selected = null;
      }

      if (newCheckedState) {
        this._radioDispatcher.notify(this.id, this.name);
      }

      this._cdr.markForCheck();
    }
  }

  private _updateValue(value: unknown): void {
    if (this._value !== value) {
      this._value = value;
      if (this._radioGroup !== null) {
        if (!this.checked) {
          this.checked = this._radioGroup.value === value;
        }
        if (this.checked) {
          this._radioGroup.selected = this;
        }
      }
    }
  }

  private _setInitialState(): void {
    if (this._radioGroup) {
      this.checked = this._radioGroup.value === this._value;

      if (this.checked) {
        this._radioGroup.selected = this;
      }

      this.name = this._radioGroup.name;
    }
  }

  private _setRadioDispatcher(): void {
    this._removeUniqueSelectionListener = this._radioDispatcher.listen((id, name) => {
      if (id !== this.id && name === this.name) {
        this.checked = false;
      }
    });
  }

  private _setFocusMonitor(): void {
    this._focusMonitor
      .monitor(this._elementRef, true)
      .pipe(takeUntil(this._destroy$))
      .subscribe((focusOrigin) => {
        if (!focusOrigin && this._radioGroup) {
          this._radioGroup._touch();
        }
      });
  }

  private _emitChangeEvent(): void {
    this.radioButtonChange.emit({ value: this._value, source: this, target: this._elementRef });
  }

  private _setDisabled(value: boolean): void {
    if (this._disabled !== value) {
      this._disabled = value;
      this._cdr.markForCheck();
    }
  }

  private _updateTabIndex(): void {
    const group = this._radioGroup;
    let value: number;

    if (!group || !group.selected || this.disabled) {
      value = this.tabIndex;
    } else {
      value = group.selected === this ? this.tabIndex : -1;
    }

    if (value !== this._previousTabIndex) {
      const inputElement: HTMLInputElement | undefined = this._inputElement?.nativeElement;

      if (inputElement) {
        inputElement.setAttribute('tabindex', value + '');
        this._previousTabIndex = value;
      }
    }
  }
}
