import { NgClass, NgIf, NgTemplateOutlet } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  HostBinding,
  HostListener,
  Input,
  OnChanges,
  Output,
  SimpleChanges,
  TemplateRef,
  ViewEncapsulation,
  booleanAttribute,
} from '@angular/core';
import { accordionAnimations } from '@questrade/allspark-angular-components/core/animations';
import { QRadioButtonVariant } from '../types/radio-button-variant.type';
import { QRadioExtraContentDensity } from '../types/radio-extra-content-density.type';
import { QRadioExtraContentPosition } from '../types/radio-extra-content-position.type';

@Component({
  imports: [NgIf, NgClass, NgTemplateOutlet],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  animations: [accordionAnimations.bodyExpansion],
  selector: 'q-radio-container',
  templateUrl: './radio-container.component.html',
  styleUrls: ['./radio-container.component.scss'],
})
export class QRadioContainerComponent implements OnChanges {
  @Output() readonly radioContainerChange = new EventEmitter<Event>();

  @Input({ transform: booleanAttribute }) expanded = false;
  @Input() extraContent: TemplateRef<unknown> | null = null;
  @Input() extraContentContext: unknown | null = null;
  @Input() extraContentDensity: QRadioExtraContentDensity = 'xs';
  @Input() extraContentPosition: QRadioExtraContentPosition = 'below';
  @Input() variant!: QRadioButtonVariant;
  @Input() disabled!: boolean;
  @Input() radioInputId!: string;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-radio-container';

  @HostBinding('class') _hostClassName = 'q-radio-container';

  @HostListener('click') _onClick = (event: Event): void => this._onContainerInteraction(event);

  ngOnChanges(changes: SimpleChanges): void {
    const { disabled } = changes || {};

    if (disabled?.currentValue) {
      this.expanded = false;
    }
  }

  _onContainerInteraction(event: Event): void {
    this.radioContainerChange.emit(event);
  }
}
