import { CDK_ACCORDION, CdkAccordionItem, CdkAccordionModule } from '@angular/cdk/accordion';
import {
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  HostBinding,
  Input,
  ViewEncapsulation,
  inject,
} from '@angular/core';
import { QRadioGroupComponent } from '../radio-group/radio-group.component';

@Component({
  imports: [CdkAccordionModule],
  viewProviders: [{ provide: CDK_ACCORDION, useExisting: QRadioGroupComponent }],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  selector: 'q-radio-expandable',
  template: `<ng-content />`,
  styleUrls: ['./radio-expandable.component.scss'],
})
export class QRadioExpandableComponent extends CdkAccordionItem {
  @Input() containerRef!: ElementRef;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-radio-expandable';
  @HostBinding('class') _hostClassName = 'q-radio-expandable';

  override accordion = inject(CDK_ACCORDION);
}
