import {
  ChangeDetectionStrategy,
  Component,
  HostBinding,
  Input,
  ViewEncapsulation,
} from '@angular/core';
import { QLineClampDirective } from '@questrade/allspark-angular-components/core/directives';

@Component({
  hostDirectives: [{ directive: QLineClampDirective, inputs: ['lineClamp'] }],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  selector: 'q-radio-label',
  template: `<ng-content />`,
  styleUrls: ['./radio-label.component.scss'],
})
export class QRadioLabelComponent {
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-radio-label';

  @HostBinding('class') hostClass = 'q-radio-label';
}
